_PA_TYPES: dict[str, Any] = {
    "str": pa.string(),
    "int": pa.int64(),
    "float": pa.float64(),
    "bool": pa.bool_(),
    "date": pa.string(),
}


def _now() -> str:
    """Return the current timestamp as an ISO 8601 string."""
    return datetime.now(timezone.utc).isoformat()


class LanceDBVectorStore(VectorStore):
    """LanceDB vector storage implementation."""

    def __init__(
        self,
        db_uri: str = "lancedb",
        fields: dict[str, str] | None = None,
        **kwargs: Any,
    ):
        super().__init__(**kwargs)
        self.db_uri = db_uri
        self.fields: dict[str, str] = fields or {}
        self._schema = self._build_schema()

    def _pa_type(self, type_str: str) -> Any:
        """Map a type string to a pyarrow type."""
        return _PA_TYPES.get(type_str, pa.string())

    def _build_schema(self) -> pa.Schema:
        """Build the pyarrow schema for the collection."""
        schema_fields = [
            pa.field(self.id_field, pa.string()),
            pa.field(self.vector_field, pa.list_(pa.float32(), self.vector_size)),
            pa.field("create_date", pa.string()),
            pa.field("update_date", pa.string()),
        ]

        # Built-in timestamp component fields (create_date + update_date).
        for name, type_str in TIMESTAMP_FIELDS.items():
            schema_fields.append(pa.field(name, self._pa_type(type_str)))

        # User-declared metadata fields.
        for fname, ftype in self.fields.items():
            if ftype == "date":
                schema_fields.append(pa.field(fname, pa.string()))
                for name, type_str in _timestamp_fields_for(fname).items():
                    schema_fields.append(pa.field(name, self._pa_type(type_str)))
            else:
                schema_fields.append(pa.field(fname, self._pa_type(ftype)))

        return pa.schema(schema_fields)

    def connect(self) -> Any:
        """Connect to the vector storage."""
        self.db_connection = lancedb.connect(self.db_uri)

        if self.index_name and self.index_name in self.db_connection.table_names():
            self.document_collection = self.db_connection.open_table(self.index_name)

    def create_index(self) -> None:
        """Create an empty index with zero documents."""
        self._schema = self._build_schema()
        self.document_collection = self.db_connection.create_table(
            self.index_name if self.index_name else "",
            schema=self._schema,
            mode="overwrite",
        )

    def _make_row(self, document: VectorStoreDocument) -> dict[str, Any]:
        """Build a table row from a document, exploding timestamp fields."""
        data = dict(document.data or {})

        create_date = data.get("create_date") or _now()
        update_date = data.get("update_date")

        if document.vector is not None:
            vector = [float(v) for v in document.vector]
        else:
            vector = [0.0] * self.vector_size

        row: dict[str, Any] = {
            self.id_field: str(document.id),
            self.vector_field: vector,
            "create_date": create_date,
            "update_date": update_date,
        }
        row.update(explode_timestamp(create_date, "create_date"))
        row.update(explode_timestamp(update_date, "update_date"))

        for fname, ftype in self.fields.items():
            value = data.get(fname)
            if ftype == "date":
                row[fname] = value
                row.update(explode_timestamp(value, fname))
            else:
                row[fname] = value

        return row

    def insert(self, document: VectorStoreDocument) -> None:
        """Insert a single document; auto-populates create_date."""
        row = self._make_row(document)
        table = pa.Table.from_pylist([row], schema=self._schema)
        self.document_collection.add(table)

    def load_documents(self, documents: list[VectorStoreDocument]) -> None:
        """Load documents into vector storage."""
        rows = [
            self._make_row(document)
            for document in documents
            if document.vector is not None
        ]
        if rows:
            table = pa.Table.from_pylist(rows, schema=self._schema)
            self.document_collection.add(table)

    def count(self) -> int:
        """Return the number of documents currently in the store."""
        return int(self.document_collection.count_rows())

    def remove(self, ids: list[str]) -> None:
        """Delete all documents whose ids appear in the list."""
        if not ids:
            return
        id_list = ", ".join(f"'{id}'" for id in ids)
        self.document_collection.delete(f"{self.id_field} IN ({id_list})")

    def update(self, document: VectorStoreDocument) -> None:
        """Update a document's fields; auto-sets update_date."""
        existing: VectorStoreDocument | None = None
        try:
            existing = self.search_by_id(str(document.id))
        except IndexError:
            existing = None

        data = dict(document.data or {})
        if not data.get("create_date") and existing and existing.data:
            data["create_date"] = existing.data.get("create_date")
        data["update_date"] = _now()

        vector = document.vector
        if vector is None and existing is not None:
