        merged = VectorStoreDocument(id=document.id, vector=vector, data=data)
        self.remove([str(document.id)])
        self.insert(merged)

    def _to_document(
        self,
        row: dict[str, Any],
        select: list[str] | None,
        include_vectors: bool,
    ) -> VectorStoreDocument:
